                                      <div key={t.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 14px", background: ti % 2 === 0 ? SURFACE : PANEL + "88", borderTop: ti > 0 ? `1px solid ${LINE}` : "none" }}>
                                        <span style={{ width: 7, height: 7, borderRadius: "50%", background: sc[t.status] || GRAY, flexShrink: 0 }} />
                                        <span style={{ fontSize: 12, color: INK, flex: 1 }}>{t.title}</span>
                                        <span style={{ fontSize: 10, color: GRAY, fontFamily: mono, whiteSpace: "nowrap" }}>{t.assignee}</span>
                                        <span style={{ fontSize: 10, fontFamily: mono, whiteSpace: "nowrap", color: t.status === "overdue" ? RISK : GRAY2, fontWeight: t.status === "overdue" ? 700 : 400 }}>{t.due}</span>
                                        <span style={{ fontSize: 9, fontWeight: 700, color: sc[t.status], background: (sc[t.status] || GRAY) + "18", borderRadius: 5, padding: "2px 6px", fontFamily: mono }}>{sl[t.status] || t.status}</span>
                                      </div>
