                  email: { to: "aurobinda@artoftechconsulting.com", subject: "Action needed: Overdue tasks review", body: `Hi Aurobinda,\n\nWe have ${overdueProjects.reduce((s,p) => s + p.overdue, 0)} overdue tasks across ${overdueProjects.length} projects that need immediate attention:\n\n${overdueProjects.map(p => `• ${p.name} — ${p.overdue} overdue task${p.overdue > 1 ? "s" : ""}`).join("\n")}\n\nPlease review and reassign or resolve these by EOD today. Share a brief status update once done.\n\nThanks,\nAmit` },
