                              <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 8px", borderRadius: 6, flexShrink: 0, background: item.type === "critical" ? RISK_BG : WARN_BG, color: item.type === "critical" ? RISK : WARN }}>{item.type === "critical" ? "Critical" : "Watch"}</span>
